using Planner.Core;
using Planner.Data;
static class FeatureUiTests
{
 static void Equal<T>(T expected,T actual){if(!Equals(expected,actual))throw new Exception($"expected {expected}, got {actual}");}
 static void Reject(Action a){try{a();}catch(ArgumentException){return;}catch(InvalidOperationException){return;}throw new Exception("expected rejection");}
 static PreparedTrip Trip(int? start=null,int duration=60)=>new(new(){Day=new(2026,10,28),Title="阅读",Location="南京图书馆",Duration=duration,Start=start},new(){Name="南京图书馆",Lng=118.79,Lat=32.04});
 public static void Register(Action<string,Action> test)
 {
  test("old WEEK preference migrates to month",()=>{var d=Path.Combine(Path.GetTempPath(),"board-migrate-"+Guid.NewGuid());Directory.CreateDirectory(d);try{File.WriteAllText(Path.Combine(d,"board.json"),"{\"view\":\"WEEK\"}");Equal("MONTH",new BoardPreferenceStore(d).Load().View);}finally{Directory.Delete(d,true);}});
  test("completion filters independently show completed and incomplete",()=>{var p=new BoardPreferences{ShowCompleted=false,ShowIncomplete=true,Completed=["a"]};Equal(false,p.IsVisible("a"));Equal(true,p.IsVisible("b"));p.ShowIncomplete=false;Equal(false,p.IsVisible("b"));});
  test("demo has varied neighboring counts and no duplicates when nonempty",()=>{var s=new PlannerState();s.Tables.Add(new(){Id="a",Name="工作"});s.Tables.Add(new(){Id="b",Name="个人"});var next=DemoSchedule.AddToEmpty(s,new(2026,10,28));var counts=BoardProjection.Range(next,new(2026,10,26),new(2026,11,1)).Select(d=>d.Entries.Count).ToArray();Equal(true,counts.Distinct().Count()>=4);Equal(true,counts.Contains(0));Equal(true,counts.Max()>=5);Equal(next.Activities.Count,DemoSchedule.AddToEmpty(next,new(2026,10,28)).Activities.Count);});
  test("calendar rows fill actual viewport with minimum for small windows",()=>{Equal(140d,BoardLayout.RowMinimum(700,5));Equal(88d,BoardLayout.RowMinimum(100,6));});
  test("repository planner chooses earliest 08 start and respects previous new request order",()=>{var a=Trip(600,120);var b=Trip(null,60);var plan=RepositoryPlanner.PlanAsync(new PlannerState(),[a,b],(_,_,_,_,_)=>Task.FromResult(new TravelEstimate(0,"同一地点"))).GetAwaiter().GetResult();Equal(600,plan.Rows[0].Start);Equal(720,plan.Rows[1].Start);});
  test("repository planner explicit overlap rejected rather than soft saved",()=>{var s=new PlannerState();s.Tables.Add(new(){Id="t"});s.Activities.Add(new(){TableId="t",Title="已有",StartAt=new(2026,10,28,10,0,0),EndAt=new(2026,10,28,11,0,0)});Reject(()=>RepositoryPlanner.PlanAsync(s,[Trip(630)],(_,_,_,_,_)=>Task.FromResult(new TravelEstimate(0,"同地"))).GetAwaiter().GetResult());});
  test("repository planner honors deadline and actual route duration",()=>{var a=Trip(600,60);var b=Trip(null,60);b.Request.LatestEnd=740;var plan=RepositoryPlanner.PlanAsync(new PlannerState(),[a,b],(_,_,_,_,_)=>Task.FromResult(new TravelEstimate(15,"夹具交通"))).GetAwaiter().GetResult();Equal(675,plan.Rows[1].Start);Equal(15,plan.Rows[1].Before.Minutes);b.Request.LatestEnd=730;Reject(()=>RepositoryPlanner.PlanAsync(new PlannerState(),[a,b],(_,_,_,_,_)=>Task.FromResult(new TravelEstimate(15,"夹具交通"))).GetAwaiter().GetResult());});
  test("repository batch cap and missing information rejected",()=>{Reject(()=>RepositoryPlanner.PlanAsync(new PlannerState(),Enumerable.Range(0,16).Select(_=>Trip()).ToArray(),(_,_,_,_,_)=>Task.FromResult(new TravelEstimate(0,""))).GetAwaiter().GetResult());var t=Trip();t.Request.Day=null;Reject(()=>RepositoryPlanner.Validate(t.Request));});
  test("repository local parsing gets date place duration and explicit time",()=>{var t=RepositoryAgentClient.ParseLocal("明天下午2点在南京博物院参观，2小时",new(2026,10,28));Equal(new DateOnly(2026,10,29),t.Day);Equal(840,t.Start);Equal(120,t.Duration);Equal("南京博物院",t.Location);});
  test("repository extract payload accepts partial events but rejects oversized batch",()=>{Equal(1,RepositoryAgentClient.ParseEvents("{\"events\":[{\"title\":\"游览\",\"day\":null,\"duration\":null}]} ").Count);Reject(()=>RepositoryAgentClient.ParseEvents("{\"events\":[]}"));});
  test("return arrival marker cannot overlap next requested stored activity",()=>{var a=Trip(600,0);a.Request.IsReturn=true;var b=Trip();var plan=RepositoryPlanner.PlanAsync(new PlannerState(),[a,b],(_,_,_,_,_)=>Task.FromResult(new TravelEstimate(0,"同地"))).GetAwaiter().GetResult();var commands=RepositoryPlanner.Commands(plan,"t");Equal(true,commands[1].Activity.StartAt>=commands[0].Activity.EndAt);});
  test("outgoing route departure includes inbound travel before candidate start",()=>{var s=new PlannerState();s.Tables.Add(new(){Id="t"});var p=new Place{Name="南京图书馆",Lng=118.79,Lat=32.04};s.Places.Add(p);s.Activities.Add(new(){TableId="t",Title="前一项",PlaceId=p.Id,StartAt=new(2026,10,28,8,0,0),EndAt=new(2026,10,28,9,0,0)});s.Activities.Add(new(){TableId="t",Title="后一项",PlaceId=p.Id,StartAt=new(2026,10,28,12,0,0),EndAt=new(2026,10,28,13,0,0)});var departures=new List<DateTime>();var plan=RepositoryPlanner.PlanAsync(s,[Trip()],(_,_,_,d,_)=>{departures.Add(d);return Task.FromResult(new TravelEstimate(15,"夹具"));}).GetAwaiter().GetResult();Equal(555,plan.Rows[0].Start);Equal(new DateTime(2026,10,28,10,15,0),departures[1]);});
  test("cancelled local extraction cannot open a stale review",()=>{using var cts=new CancellationTokenSource();cts.Cancel();bool cancelled=false;try{new RepositoryAgentClient().ExtractAsync(new(){AgentProvider="LOCAL"},"明天在南京博物院参观，2小时",cts.Token).GetAwaiter().GetResult();}catch(OperationCanceledException){cancelled=true;}Equal(true,cancelled);});
  test("model extraction fixture uses repository events contract and preserves notes",()=>{string captured="";using var http=new System.Net.Http.HttpClient(new FixtureHandler(async request=>{captured=await request.Content!.ReadAsStringAsync();return new(System.Net.HttpStatusCode.OK){Content=new System.Net.Http.StringContent(System.Text.Json.JsonSerializer.Serialize(new{choices=new[]{new{message=new{content="{\"events\":[{\"day\":\"2026-10-29\",\"title\":\"参观南京博物院\",\"location\":\"南京博物院\",\"duration\":120,\"notes\":\"带学生证\"}]}"}}}}))};}));var rows=new RepositoryAgentClient(http).ExtractAsync(new(){AgentProvider="CUSTOM",LlmEndpoint="http://localhost/v1",Model="fixture"},"明天参观",default).GetAwaiter().GetResult();Equal("带学生证",rows[0].Notes);using var doc=System.Text.Json.JsonDocument.Parse(captured);Equal("fixture",doc.RootElement.GetProperty("model").GetString());Equal(true,doc.RootElement.GetProperty("messages")[0].GetProperty("content").GetString()!.Contains("events"));});
  test("legacy nested overlapping events never create a false free gap",()=>{var s=new PlannerState();s.Tables.Add(new(){Id="t"});var p=new Place{Name="南京图书馆",Lng=118.79,Lat=32.04};s.Places.Add(p);s.Activities.Add(new(){TableId="t",Title="长活动",PlaceId=p.Id,StartAt=new(2026,10,28,8,0,0),EndAt=new(2026,10,28,14,0,0)});s.Activities.Add(new(){TableId="t",Title="嵌套活动",PlaceId=p.Id,StartAt=new(2026,10,28,9,0,0),EndAt=new(2026,10,28,10,0,0)});var plan=RepositoryPlanner.PlanAsync(s,[Trip()],(_,_,_,_,_)=>Task.FromResult(new TravelEstimate(0,"同地"))).GetAwaiter().GetResult();Equal(true,plan.Rows[0].Start>=840);});
  test("new weekly overlap beyond first fortnight is detected with dated key",()=>{var before=new PlannerState();before.Tables.Add(new(){Id="t"});before.Activities.Add(new(){Id="b",TableId="t",Title="未来预约",StartAt=new(2026,11,25,10,0,0),EndAt=new(2026,11,25,11,0,0)});var after=ChangeService.Apply(before,[new(){Activity=new(){Id="a",TableId="t",Title="新周期",Kind="WEEKLY",DurationMin=60},Rule=new(){ActivityId="a",ValidFrom=new(2026,10,28),WeekMask=4,StartTime="10:00"}}],0);Equal(true,EditConflictGuard.ForEdit(before,after,new(2026,10,28)).Count>0);});
  test("future weekly split new identity cannot bypass overlap guard",()=>{var before=new PlannerState();before.Tables.Add(new(){Id="t"});var a=new Planner.Core.Activity{Id="a",TableId="t",Title="原周期",Kind="WEEKLY",DurationMin=60};before.Activities.Add(a);before.Rules.Add(new(){ActivityId="a",ValidFrom=new(2026,10,1),WeekMask=4,StartTime="09:00"});before.Activities.Add(new(){Id="b",TableId="t",Title="预约",StartAt=new(2026,10,28,10,0,0),EndAt=new(2026,10,28,11,0,0)});var copy=JsonKit.Clone(a);copy.StartAt=new(2026,10,28,10,0,0);copy.EndAt=new(2026,10,28,11,0,0);var after=ChangeService.Apply(before,[new(){Activity=copy,Scope="FUTURE",SplitDate=new(2026,10,28),OriginDate=new(2026,10,28),Rule=new(){ValidFrom=new(2026,10,28),WeekMask=4,StartTime="10:00"}}],0);Equal(true,EditConflictGuard.ForEdit(before,after,new(2026,10,28)).Count>0);});
 }
}

sealed class FixtureHandler(Func<System.Net.Http.HttpRequestMessage,Task<System.Net.Http.HttpResponseMessage>> respond):System.Net.Http.HttpMessageHandler
{
 protected override Task<System.Net.Http.HttpResponseMessage> SendAsync(System.Net.Http.HttpRequestMessage request,CancellationToken token)=>respond(request);
}
